function ConceptSearchWorkspace({ navigate }: { navigate:(module:string,sub?:string,detail?:string)=>void }) {
  const [query,setQuery]=useState("");
  const [scope,setScope]=useState<"all"|"recent"|"saved"|"suggested"|"modes">("all");
  const [showFilters,setShowFilters]=useState(false);
  const [showWhy,setShowWhy]=useState(false);
  const searchRef=useRef<HTMLInputElement>(null);
  const normalized=query.trim().toLowerCase();
  const results=useMemo(()=>conceptTopics.filter(topic=>{
    const matchesQuery=!normalized||`${topic.title} ${topic.subject} ${topic.context} ${topic.mode}`.toLowerCase().includes(normalized);
    const matchesScope=scope==="all"||scope==="modes"||topic[scope];
    return matchesQuery&&matchesScope;
  }),[normalized,scope]);
  const openConcept=(title:string)=>navigate("AI Study Buddy","Explain a Concept",title);
  const selectScope=(next:typeof scope)=>{setScope(next);setShowFilters(false)};
  const beginSearch=()=>{setScope("all");requestAnimationFrame(()=>searchRef.current?.focus())};
  return <div className="page-stack concept-search-page">
    <section className="title-row"><div><Badge tone="ai">AI STUDY BUDDY</Badge><h1>Understand Any Concept</h1><p>Choose how you want a concept explained and explore it interactively.</p></div><Button variant="primary" icon="spark" onClick={beginSearch}>Explain a concept</Button></section>
    <LearnerIntelligenceStrip compact/>
    <div className="concept-metric-grid">
      {[
        ["recent","12","RECENT CONCEPTS","Updated today","trend","blue"],
        ["modes","5","LEARNING MODES","Personalized","brain","violet"],
        ["saved","24","SAVED EXPLANATIONS","Synced to library","clock","cyan"],
        ["suggested","3","SUGGESTED NEXT","Based on mastery","trophy","amber"],
      ].map(([key,value,label,note,icon,color])=><button className={`card concept-metric ${scope===key?"active":""} tone-${color}`} key={label} onClick={()=>selectScope(key as typeof scope)}><span className="concept-metric-icon"><Icon name={icon as IconName}/></span><span><small>{label}</small><strong>{value}</strong><em>{note}</em></span><Sparkline values={key==="saved"?[25,38,32,49,43,61,70]:[30,40,35,52,47,66,76]} color={color==="violet"?"violet":color==="cyan"?"cyan":"blue"}/></button>)}
    </div>
    <div className="concept-discovery-grid">
      <section className="card concept-results">
        <div className="section-head"><div><span className="eyebrow">EXPLAIN A CONCEPT</span><h2>{normalized?`${results.length} curriculum ${results.length===1?"match":"matches"}`:scope==="all"?"Recommended and recent concepts":scope==="modes"?"Explore every explanation mode":`${scope[0].toUpperCase()+scope.slice(1)} concepts`}</h2></div><Button icon="filter" onClick={()=>setShowFilters(!showFilters)}>{scope==="all"?"Filter":scope[0].toUpperCase()+scope.slice(1)}</Button></div>
        {showFilters&&<div className="concept-filter-menu">{(["all","recent","saved","suggested"] as const).map(option=><button className={scope===option?"active":""} key={option} onClick={()=>selectScope(option)}>{option==="all"?"All concepts":option[0].toUpperCase()+option.slice(1)}{scope===option&&<Icon name="check" size={13}/>}</button>)}</div>}
        <div className="concept-search-inline">
          <div className="concept-search-input"><Icon name="search" size={19}/><input ref={searchRef} value={query} onChange={e=>setQuery(e.target.value)} onKeyDown={e=>e.key==="Enter"&&results[0]&&openConcept(results[0].title)} placeholder="Search a concept, topic, or question..." aria-label="Search concepts"/>{query&&<button onClick={()=>setQuery("")} aria-label="Clear concept search"><Icon name="close" size={15}/></button>}<Button variant="primary" onClick={()=>results[0]&&openConcept(results[0].title)}>Explain</Button></div>
          <div className="concept-search-hints"><span>Try:</span>{["Completing the square","Trigonometric ratios","Newton's laws"].map(topic=><button key={topic} onClick={()=>{setScope("all");setQuery(topic)}}>{topic}</button>)}</div>
        </div>
        <div className="concept-result-list">{results.map((topic,i)=><button key={topic.title} onClick={()=>openConcept(topic.title)}><span className={`list-icon tone-${i%2?"violet":"blue"}`}><Icon name={topic.subject==="Mathematics"?"brain":"book"}/></span><span className="concept-result-copy"><small>{topic.subject.toUpperCase()} · {topic.level.toUpperCase()}</small><strong>{topic.title}</strong><em>{topic.context}</em></span><Badge>{topic.mode}</Badge><Icon name="chevron"/></button>)}</div>
        {!results.length&&<div className="concept-empty"><span className="ai-orb"><Icon name="search"/></span><h2>No exact curriculum match yet</h2><p>Try a broader topic or explain it in your own words. AI Study Buddy can still help you explore it.</p><Button variant="primary" icon="spark" onClick={()=>openConcept(query)}>Explain “{query}”</Button></div>}
      </section>
      <aside className="card concept-recent concept-next-action">
        <div className="ai-orb"><Icon name="spark"/></div><Badge tone="ai">NEXT BEST ACTION</Badge>
        <h2>Continue with Completing the square while the prerequisite concepts are fresh.</h2>
        <p>Recommended from your current Algebra goal and recent practice activity.</p>
        <button className="why-toggle" onClick={()=>setShowWhy(!showWhy)}>Why is this recommended? <Icon name={showWhy?"arrow":"chevron"} size={13}/></button>
        {showWhy&&<div className="recommendation-reason"><Icon name="brain" size={15}/><p>Your last two Algebra activities used the quadratic formula successfully. Completing the square is the next curriculum-aligned representation to strengthen.</p></div>}
        <div className="evidence-list"><span><small>MASTERY SIGNAL</small><strong>72% · Developing</strong></span><span><small>ESTIMATED TIME</small><strong>8 minutes</strong></span></div>
        <Button variant="primary" className="full" onClick={()=>openConcept("Completing the square")}>Open explanation</Button>
        <hr/>
        <span className="eyebrow">BROWSE BY SUBJECT</span>
        <div className="subject-pills">{["SAP","Oracle Apps","RDBMS","Java",".NET","Testing","BI","SFDC","Infra & Networking","Mainframe","AI"].map(subject=><button key={subject} onClick={()=>{setScope("all");setQuery(subject);searchRef.current?.focus()}}>{subject}</button>)}</div>
      </aside>
    </div>
  </div>;
}

const learningPathModules = [
  { id:"foundation", number:"01", title:"Algebra Foundations", description:"Refresh expressions, equations and essential notation.", progress:100, status:"Complete", lessons:["Expressions and variables","Solving linear equations","Algebra readiness check"] },
  { id:"quadratics", number:"02", title:"Quadratic Expressions", description:"Factor, transform and solve quadratic expressions.", progress:68, status:"In progress", lessons:["Recognizing quadratic form","Factorization strategies","Completing the square","Quadratic formula","Module mastery check"] },
  { id:"functions", number:"03", title:"Functions & Graphs", description:"Connect equations to visual representations and behavior.", progress:0, status:"Next", lessons:["Function notation","Domain and range","Graph transformations","Interpreting key features"] },
  { id:"modeling", number:"04", title:"Mathematical Modeling", description:"Use functions to represent and solve contextual problems.", progress:0, status:"Locked", lessons:["Building a model","Testing assumptions","Interpreting solutions"] },
  { id:"mastery", number:"05", title:"Algebra Mastery", description:"Integrate concepts through practice and a final challenge.", progress:0, status:"Locked", lessons:["Mixed practice","Applied challenge","Final mastery assessment"] },
];

function LearningPathWorkspace({ navigate, moduleName="AI Study Buddy" }: { navigate:(module:string,sub?:string,detail?:string)=>void; moduleName?:string }) {
  const [courses,setCourses]=useState<CourseRecord[]>([]);
  const [courseId,setCourseId]=useState("");
  const [pathLessons,setPathLessons]=useState<{id:string;title:string}[]>([]);
  useEffect(()=>{
    if(!getStoredToken()) return;
    apiFetch<CourseRecord[]>("/api/v1/courses").then(rows=>{setCourses(rows);if(rows[0]) setCourseId(rows[0].id);}).catch(()=>setCourses([]));
  },[]);
  useEffect(()=>{
    if(!courseId||!getStoredToken()) return;
    apiFetch<{id:string;title:string}[]>(`/api/v1/courses/${courseId}/lessons`).then(setPathLessons).catch(()=>setPathLessons([]));
  },[courseId]);
  const active=courses.find(course=>course.id===courseId);
  const pathTitle=active?`Your route through ${active.title}`:"Your learning path";
  const resume=()=>{
    if(active&&pathLessons[0]) navigate("Courses","My Courses",`lesson:${active.id}:${pathLessons[0].id}:${encodeURIComponent(pathLessons[0].title)}`);
    else if(active) navigate("Courses","My Courses",`cid:${active.id}`);
  };
  return <div className="page-stack learning-path-page">
    <section className="title-row"><div><Badge tone="ai">PERSONALIZED LEARNING PATH</Badge><h1>{pathTitle}</h1><p>{active?`Modules and lessons follow ${active.title}. Other subjects stay in their own courses.`:"Sign in to load a path from your enrolled courses."}</p></div><Button variant="primary" icon="play" onClick={resume}>Continue learning</Button></section>
    {courses.length>0&&<div className="course-category-filter">{courses.slice(0,8).map(course=><button className={course.id===courseId?"active":""} key={course.id} onClick={()=>setCourseId(course.id)}>{course.title}</button>)}</div>}
    <LearnerIntelligenceStrip compact/>
    <section className="card path-progress-hero"><div><span className="eyebrow">ACTIVE LEARNING PATH</span><h2>{active?.title||"Choose an enrolled course"}</h2><p>{pathLessons.length?`${pathLessons.length} lessons in this course.`:"Lessons appear after the course is selected."}</p></div><div className="path-progress-score"><strong>{active?.progress_pct??0}%</strong><small>PATH PROGRESS</small></div><div className="path-progress-track"><i style={{width:`${active?.progress_pct??0}%`}}/><span>{pathLessons.length} lessons</span></div></section>
    <div className="learning-path-layout">
      <section className="card path-map">
        <div className="section-head"><div><span className="eyebrow">MASTERY SEQUENCE</span><h2>Your adaptive route</h2></div><Badge tone="ai">PERSONALIZED</Badge></div>
        <div className="path-module-list">{(pathLessons.length?pathLessons.map((lesson,index)=>({id:lesson.id,number:String(index+1).padStart(2,"0"),title:lesson.title,description:active?.title||"This course",progress:index===0?40:0,status:index===0?"In progress":"Ready",lessons:[lesson.title]})):active?[]:learningPathModules).map((module,index)=><button className={module.status.toLowerCase().replace(" ","-")} key={module.id} onClick={()=>pathLessons.length?navigate("Courses","My Courses",`lesson:${courseId}:${module.id}:${encodeURIComponent(module.title)}`):navigate(moduleName,"My Learning Path",`module:${module.id}`)}><span className="path-module-number">{module.number}</span><span className="path-module-copy"><small>{module.status.toUpperCase()}</small><strong>{module.title}</strong><em>{module.description}</em><span className="path-module-progress"><i style={{width:`${module.progress}%`}}/></span></span><Badge tone={module.status==="In progress"?"ai":"default"}>{module.progress}%</Badge><Icon name="chevron"/>{(index+1)<(pathLessons.length||learningPathModules.length)&&<span className="path-connector"/>}</button>)}</div>
      </section>
      <aside className="card path-coach">
        <div className="ai-orb"><Icon name="spark"/></div><Badge tone="ai">NEXT BEST STEP</Badge><h2>{pathLessons[0]?`Continue ${pathLessons[0].title}`:"Open your enrolled course"}</h2><p>The next step stays inside {active?.title||"the course you select"}.</p>
        <Button variant="primary" className="full" onClick={resume}>Resume lesson</Button>
        <hr/><span className="eyebrow">WEEKLY GOAL</span><div className="weekly-goal"><span><strong>3 of 4</strong><small>focused sessions</small></span><div className="progress"><i style={{width:"75%"}}/></div><small>One more session keeps you on pace.</small></div>
      </aside>
    </div>
  </div>;
}

function LearningPathDetail({ detail, navigate, moduleName="AI Study Buddy" }: { detail:string; navigate:(module:string,sub?:string,detail?:string)=>void; moduleName?:string }) {
  const [answer,setAnswer]=useState<number|null>(null);
  const [completed,setCompleted]=useState(false);
  const parts=detail.split(":");
  const moduleId=parts[1]||"quadratics";
  const module=learningPathModules.find(item=>item.id===moduleId)||learningPathModules[1];
  const isLesson=parts[0]==="lesson";
  const lessonTitle=parts.slice(2).join(":")||module.lessons[0];
  if(isLesson) return <div className="page-stack path-lesson-page">
    <WorkspaceBack title={lessonTitle} onBack={()=>navigate(moduleName,"My Learning Path",`module:${module.id}`)}/>
    <div className="path-lesson-layout">
      <main className="card path-lesson-main">
        <div className="lesson-breadcrumb"><Badge tone="ai">{module.title.toUpperCase()}</Badge><span>Activity {Math.max(1,module.lessons.indexOf(lessonTitle)+1)} of {module.lessons.length}</span></div>
        <h1>{lessonTitle}</h1><p className="lead">Build understanding through a short explanation, worked example and confidence check.</p>
        <div className="lesson-objectives"><span className="eyebrow">BY THE END OF THIS ACTIVITY</span><div><span><Icon name="check"/>Recognize when this strategy is useful</span><span><Icon name="check"/>Apply the process to a worked example</span><span><Icon name="check"/>Explain why each step preserves equality</span></div></div>
        <div className="path-worked-example"><span className="eyebrow">WORKED EXAMPLE</span><h2>Rewrite the expression in vertex form</h2><div className="formula">x² + 6x + 5 = (x + 3)² − 4</div><p>Half of 6 is 3. Add and subtract 9, then simplify the constant terms without changing the expression’s value.</p></div>
        <section className="path-knowledge-check"><span className="eyebrow">QUICK CHECK</span><h2>What value completes the square for x² + 8x?</h2>{["4","8","16","64"].map((option,index)=><button className={answer===index?(index===2?"correct":"incorrect"):""} key={option} onClick={()=>setAnswer(index)}><span>{String.fromCharCode(65+index)}</span>{option}{answer===index&&<Icon name={index===2?"check":"close"}/>}</button>)}{answer!==null&&<div className={`check-feedback ${answer===2?"success":"retry"}`}><Icon name={answer===2?"check":"warning"}/><p>{answer===2?"Correct. Half of 8 is 4, and 4² is 16.":"Not quite. Take half of the x coefficient first, then square that value."}</p></div>}</section>
        <div className="panel-actions"><Button onClick={()=>navigate("AI Study Buddy","Explain a Concept",lessonTitle)}>Explain differently</Button><Button variant="primary" icon="check" onClick={()=>setCompleted(true)}>{completed?"Activity completed":"Mark complete"}</Button></div>
      </main>
      <aside className="card path-lesson-rail"><span className="eyebrow">ACTIVITY PROGRESS</span><div className={`lesson-ring ${completed?"complete":""}`}><strong>{completed?"100%":"60%"}</strong><small>{completed?"Complete":"In progress"}</small></div><div className="evidence-list"><span><small>TIME LEFT</small><strong>{completed?"Done":"6 min"}</strong></span><span><small>XP</small><strong>+120</strong></span></div><hr/><span className="eyebrow">UP NEXT</span><h2>{module.lessons[Math.min(module.lessons.indexOf(lessonTitle)+1,module.lessons.length-1)]}</h2><Button className="full" onClick={()=>navigate(moduleName,"My Learning Path",`module:${module.id}`)}>View module</Button></aside>
    </div>
  </div>;
  return <div className="page-stack path-module-page">
    <WorkspaceBack title={module.title} onBack={()=>navigate(moduleName,"My Learning Path")}/>
    <section className="card path-module-hero"><div><Badge tone={module.status==="Complete"?"success":"ai"}>{module.status.toUpperCase()}</Badge><h1>{module.title}</h1><p>{module.description}</p><div className="path-module-meta"><span><Icon name="book"/> {module.lessons.length} activities</span><span><Icon name="clock"/> 1 hr 25 min</span><span><Icon name="brain"/> Target mastery 80%</span></div></div><div className="path-progress-score"><strong>{module.progress}%</strong><small>MODULE PROGRESS</small></div></section>
    <div className="path-module-layout">
      <section className="card module-activity-list"><div className="section-head"><div><span className="eyebrow">LEVEL 2 · MODULE PLAN</span><h2>Activities and mastery checks</h2></div><Badge>{module.lessons.filter((_,i)=>i<2).length} COMPLETE</Badge></div>{module.lessons.map((lesson,index)=><button className={index<2?"complete":index===2?"current":""} key={lesson} onClick={()=>navigate(moduleName,"My Learning Path",`lesson:${module.id}:${lesson}`)}><span>{index<2?<Icon name="check"/>:index+1}</span><span><small>{index===module.lessons.length-1?"MASTERY CHECK":index<2?"COMPLETED":index===2?"CONTINUE HERE":"LESSON"}</small><strong>{lesson}</strong><em>{index===2?"14 min · Interactive explanation":index===module.lessons.length-1?"10 questions · Target 80%":"12 min · Lesson and practice"}</em></span><Badge tone={index<2?"success":index===2?"ai":"default"}>{index<2?"DONE":index===2?"ACTIVE":"READY"}</Badge><Icon name="chevron"/></button>)}</section>
      <aside className="card module-outcomes"><span className="eyebrow">MODULE OUTCOMES</span><h2>What you will master</h2>{["Identify quadratic structure","Select an efficient solving strategy","Interpret roots and turning points"].map(outcome=><span key={outcome}><Icon name="check" size={14}/>{outcome}</span>)}<hr/><span className="eyebrow">PREREQUISITE EVIDENCE</span><div className="evidence-list"><span><small>LINEAR EQUATIONS</small><strong>92%</strong></span><span><small>EXPANDING BRACKETS</small><strong>88%</strong></span></div><Button variant="primary" className="full" onClick={()=>navigate(moduleName,"My Learning Path",`lesson:${module.id}:${module.lessons[Math.min(2,module.lessons.length-1)]}`)}>Continue module</Button></aside>
    </div>
  </div>;
}

function StudyFunctionWorkspace({ sub, detail, navigate }: { sub:string; detail:string; navigate:(module:string,sub?:string,detail?:string)=>void }) {
  if(detail) return <StudyActionDetail sub={sub} detail={detail} navigate={navigate}/>;
  if(sub==="Explain a Concept") return <ConceptSearchWorkspace navigate={navigate}/>;
  if(sub==="My Learning Path") return <LearningPathWorkspace navigate={navigate}/>;
  const data=studyFunctions[sub]||studyFunctions["My Learning Path"];
  return <div className="page-stack"><section className="title-row"><div><Badge tone="ai">AI STUDY BUDDY</Badge><h1>{data.title}</h1><p>{data.description}</p></div><Button variant="primary" icon="spark" onClick={()=>navigate("AI Study Buddy",sub,"Open Workspace")}>{sub==="Study Planner"?"Generate plan":sub==="Explain a Concept"?"Explain a concept":"Start now"}</Button></section><LearnerIntelligenceStrip compact/><div className="kpi-grid compact">{data.metrics.map(([v,l],i)=><Kpi key={l} label={l.toUpperCase()} value={v} delta={i===0?"Updated today":"Personalized"} icon={(["trend","brain","clock","trophy"] as IconName[])[i]} color={i===1?"violet":i===2?"cyan":i===3?"amber":"blue"}/>)}</div><div className="content-grid"><section className="card span-2"><div className="section-head"><div><span className="eyebrow">{sub.toUpperCase()}</span><h2>{sub==="Practice With AI"?"Choose a practice mode":sub==="Explain a Concept"?"Recommended and recent concepts":"Your intelligent workspace"}</h2></div><Button icon="filter">Filter</Button></div><div className="deep-action-list">{data.items.map(([a,b,c],i)=><button key={a+b} onClick={()=>navigate("AI Study Buddy",sub,b)}><span className={`list-icon tone-${i%2?"violet":"blue"}`}><Icon name={sub==="Flashcards"?"file":sub==="Study Planner"?"calendar":sub==="Practice With AI"?"assessment":"spark"}/></span><span><small>{a.toUpperCase()}</small><strong>{b}</strong></span><Badge>{c}</Badge><Icon name="chevron"/></button>)}</div></section><aside className="card explain-card"><div className="ai-orb"><Icon name="spark"/></div><Badge tone="ai">NEXT BEST ACTION</Badge><h2>{sub==="Exam Preparation"?"Complete a short Trigonometry practice before your mock exam.":sub==="Smart Revision"?"Review Trigonometry today because estimated retention has declined.":"Continue with Quadratic Expressions while the prerequisite concepts are fresh."}</h2><button className="why-toggle">Why is this recommended?</button><div className="evidence-list"><span><small>EVIDENCE</small><strong>Last 3 activities</strong></span><span><small>CONFIDENCE</small><strong>84% · Estimate</strong></span><span><small>HUMAN REVIEW</small><strong>Not high-stakes</strong></span></div><Button variant="primary" className="full" onClick={()=>navigate("AI Study Buddy",sub,"Recommendation Detail")}>Open recommendation</Button></aside></div></div>;
}

function StudyActionDetail({ sub, detail, navigate }: { sub:string; detail:string; navigate:(module:string,sub?:string,detail?:string)=>void }) {
  const [confidence,setConfidence]=useState(0);const [flipped,setFlipped]=useState(false);const [answered,setAnswered]=useState(false);
  if(sub==="My Learning Path") return <LearningPathDetail detail={detail} navigate={navigate}/>;
  if(sub==="Practice With AI") return <div className="page-stack"><WorkspaceBack title="Intelligent Practice Session" onBack={()=>navigate("AI Study Buddy",sub)}/><LearnerIntelligenceStrip compact/><section className="practice-session card"><div className="practice-progress"><span>QUESTION 4 OF 10</span><div className="progress"><i style={{width:"40%"}}/></div><Badge tone="warning">MEDIUM</Badge></div><div className="question-meta"><span>Competency: Quadratic Equations</span><span>Mastery: 72%</span><span>Confidence: Developing</span></div><h1>Which expression is equivalent to x² + 6x + 5?</h1>{["(x + 3)² − 4","(x + 3)² + 4","(x − 3)² − 4","(x + 6)² − 31"].map((x,i)=><button className={`answer-option ${answered&&i===0?"correct":""}`} key={x}>{String.fromCharCode(65+i)}<span>{x}</span>{answered&&i===0&&<Icon name="check"/>}</button>)}{answered&&<div className="answer-feedback"><Icon name="check"/><div><strong>Correct</strong><p>Half of 6 is 3, and 3² is 9. Therefore x² + 6x + 5 = (x + 3)² − 4.</p><small>Mastery impact: +3% · Next difficulty: Medium → Hard</small></div></div>}<div className="practice-actions"><Button>Hint</Button><Button onClick={()=>navigate("AI Study Buddy","Explain a Concept","Quadratic Equations")}>Explain concept</Button><Button>Skip</Button><Button variant="primary" onClick={()=>setAnswered(true)}>{answered?"Next question":"Submit answer"}</Button></div></section></div>;
  if(sub==="Flashcards") return <div className="page-stack"><WorkspaceBack title="Interactive Flashcards" onBack={()=>navigate("AI Study Buddy",sub)}/><section className="flashcard-shell"><div className={`flashcard ${flipped?"flipped":""}`} onClick={()=>setFlipped(!flipped)}><Badge>QUADRATIC EQUATIONS · 4 OF 12</Badge><span className="eyebrow">{flipped?"ANSWER":"CONCEPT"}</span><h1>{flipped?"A quadratic equation has the form ax² + bx + c = 0, where a ≠ 0.":"What defines a quadratic equation?"}</h1>{flipped&&<p>Example: 2x² + 5x − 3 = 0. Its highest exponent is 2.</p>}<small><Icon name="more"/> Click to flip</small></div><div className="recall-actions">{["Again","Hard","Good","Easy"].map((x,i)=><button className={`recall-${i}`} key={x}>{x}<small>{["1 min","3 days","7 days","14 days"][i]}</small></button>)}</div><p className="center-note">Your response adjusts the next estimated review date.</p></section></div>;
  if(sub==="Explain a Concept"||sub==="Ask AI") {
    const concept=detail==="Open Workspace"||detail==="Recommendation Detail"?"Completing the square":detail;
    const isCompleting=concept==="Completing the square";
    return <div className="page-stack"><WorkspaceBack title="Contextual Answer Workspace" onBack={()=>navigate("AI Study Buddy",sub)}/><LearnerIntelligenceStrip compact/><section className="explanation-layout"><main className="card explanation-main"><Badge tone="ai">CONCEPT · CURRICULUM GROUNDED</Badge><h1>{concept}</h1><p className="lead">{isCompleting?"Completing the square rewrites a quadratic expression so its squared structure becomes visible.":`A contextual introduction to ${concept}, connected to your current curriculum and learning progress.`}</p><div className="tabs"><button className="active">Overview</button><button>Step-by-Step</button><button>Example</button><button>Visual</button><button>Practice</button><button>Ask AI</button></div><div className="explanation-section"><span className="eyebrow">SIMPLE EXPLANATION</span><h2>{isCompleting?"Turn an almost-square into a perfect square":`Build an intuitive understanding of ${concept}`}</h2><p>{isCompleting?"Take half of the x coefficient, square it, then add and subtract that value so the expression remains equal.":`Start with the core idea, connect it to what you already know, then test it with a worked example.`}</p>{isCompleting&&<div className="formula">x² + 6x + 5 = (x + 3)² − 4</div>}</div><div className="explanation-columns"><div><span className="eyebrow">REAL-LIFE CONNECTION</span><h2>{isCompleting?"Finding the peak of a path":"See the idea in context"}</h2><p>{isCompleting?"Vertex form helps identify the highest or lowest point of a curved trajectory.":"Your explanation adapts examples from the subject and level in your course."}</p></div><div><span className="eyebrow">LEARNING TIP</span><h2>{isCompleting?"Remember to balance":"Connect before memorizing"}</h2><p>{isCompleting?"Whatever value you add must also be subtracted to preserve equality.":"Link the new idea to a familiar prerequisite before moving into practice."}</p></div></div><div className="source-box"><Icon name="file"/><span><strong>Grounded in course sources</strong><small>Matched curriculum resources and current learning context</small></span><Button variant="ghost">View sources</Button></div></main><aside className="card concept-sidebar"><div className="sidebar-search-action"><Button icon="search" className="full" onClick={()=>navigate("AI Study Buddy","Explain a Concept")}>Search another concept</Button></div><hr/><span className="eyebrow">PREREQUISITES</span>{["Core vocabulary · Ready","Prior lesson · 76%","Related concept · 92%"].map(x=><button key={x}>{x}<Icon name="chevron"/></button>)}<hr/><span className="eyebrow">CONFIDENCE CHECK</span><h2>How confident are you?</h2><div className="confidence-scale">{[1,2,3,4,5].map(x=><button className={confidence===x?"active":""} onClick={()=>setConfidence(x)} key={x}>{x}</button>)}</div><small>{confidence?"Learner profile updated":"Select 1 (not yet) to 5 (very confident)"}</small></aside></section><div className="sticky-learning-actions">{["I Understand","Explain Differently","Give Another Example","Practice This","Quiz Me","Add to Revision"].map((x,i)=><Button variant={i===0?"primary":"secondary"} onClick={()=>i===3&&navigate("AI Study Buddy","Practice With AI","Quadratic Practice")} key={x}>{x}</Button>)}</div></div>;
  }
  if(sub==="Study Planner") return <div className="page-stack"><WorkspaceBack title="AI Plan Generator" onBack={()=>navigate("AI Study Buddy",sub)}/><div className="planner-grid"><section className="card plan-form"><h2>Plan around your goals</h2>{[["Exam date","June 9, 2025"],["Available study time","5 hours / week"],["Subjects","Mathematics, Physics"],["Priority","Mathematics exam"],["Current mastery","72%"],["Learning goal","Reach 85% mastery"]].map(([x,v])=><label key={x}>{x}<input defaultValue={v}/></label>)}<Button variant="primary" icon="wand" className="full">Regenerate plan</Button></section><section className="card week-plan"><div className="section-head"><div><Badge tone="ai">AI-GENERATED PLAN</Badge><h2>Recommended study week</h2></div><Badge tone="success">NO CONFLICTS</Badge></div>{[["Monday","Math · Quadratics","45 min"],["Tuesday","Physics · Mechanics","30 min"],["Wednesday","Math Revision","30 min"],["Thursday","Rest & light recall","15 min"],["Friday","Mock exam practice","60 min"]].map(([d,x,t])=><div className="plan-row" key={d}><strong>{d}</strong><span>{x}</span><Badge>{t}</Badge><Icon name="more"/></div>)}<div className="panel-actions"><Button>Modify</Button><Button>Set reminders</Button><Button variant="primary">Accept plan</Button></div></section></div></div>;
  return <GenericActionDetail title={sub} onBack={()=>navigate("AI Study Buddy",sub)}/>;
}

function WorkspaceBack({title,onBack}:{title:string;onBack:()=>void}){return <section className="workspace-back"><button onClick={onBack}><Icon name="arrow"/> Back</button><div><Badge tone="ai">FUNCTIONAL WORKSPACE</Badge><h1>{title}</h1></div></section>}
