function DigitalLibraryWorkspace({sub,detail,navigate,role}:{sub:string;detail:string;navigate:(module:string,sub?:string,detail?:string)=>void;role:Role}) {
  const [query,setQuery]=useState("");
  const [saved,setSaved]=useState<string[]>(["SQL Query Optimization Lab"]);
  const [searchConfirmed,setSearchConfirmed]=useState(false);
  const [collectionCreated,setCollectionCreated]=useState(false);
  const menu=submodules["Digital Library"];
  const visible=libraryResources.filter(item=>(sub==="Explore"||sub==="AI Search"||sub==="My Library"&&saved.includes(item.title)||item.type===sub)&&`${item.title} ${item.subject} ${item.type}`.toLowerCase().includes(query.toLowerCase()));
  if(detail==="New Collection") return <div className="page-stack"><WorkspaceBack title="Create collection" onBack={()=>navigate("Digital Library","Collections")}/><section className="card classroom-form"><div className="section-head"><div><span className="eyebrow">RESOURCE COLLECTION</span><h2>Create a curated learning collection</h2></div>{collectionCreated&&<Badge tone="success">CREATED</Badge>}</div><div className="form-grid"><label>Collection name<input defaultValue="Enterprise Technology Foundations"/></label><label>Visibility<select><option>Private</option><option>My class</option><option>Institution</option></select></label></div><label className="assignment-long-field">Description<textarea defaultValue="Core resources for SAP, Oracle, databases, Java, infrastructure and AI learning paths."/></label><AudienceSelector label="Share collection with"/><div className="panel-actions"><Button>Save draft</Button><Button variant="primary" icon="check" onClick={()=>setCollectionCreated(true)}>{collectionCreated?"Collection created":"Create collection"}</Button></div></section></div>;
  if(detail) {const resource=libraryResources.find(item=>item.title===detail)||libraryResources[0];return <div className="page-stack"><WorkspaceBack title={resource.title} onBack={()=>navigate("Digital Library",sub)}/><section className="card library-reader"><div className="library-reader-cover"><Icon name={resource.type==="Videos"?"play":"book"} size={54}/><Badge>{resource.type.toUpperCase()}</Badge></div><div><Badge tone="ai">{resource.subject}</Badge><h1>{resource.title}</h1><p>{resource.meta}. This synthetic learning resource is mapped to the enterprise technology curriculum and available for guided study.</p><div className="lesson-objectives"><span className="eyebrow">RESOURCE OUTCOMES</span><div><span><Icon name="check"/>Understand the core concepts</span><span><Icon name="check"/>Apply the workflow in context</span><span><Icon name="check"/>Complete the knowledge check</span></div></div><div className="row-actions"><Button onClick={()=>setSaved(saved.includes(resource.title)?saved.filter(x=>x!==resource.title):[...saved,resource.title])}>{saved.includes(resource.title)?"Saved to library":"Save resource"}</Button><Button variant="primary" icon="play" onClick={()=>setSearchConfirmed(true)}>{searchConfirmed?"Learning started":"Start learning"}</Button></div></div></section></div>}
  return <div className="page-stack"><section className="title-row"><div><Badge tone="ai">DIGITAL LIBRARY</Badge><h1>{sub}</h1><p>{sub==="AI Search"?"Ask in natural language and search trusted, curriculum-mapped learning resources.":sub==="My Library"?"Return to saved resources and continue learning.":"Search across trusted learning resources using natural language."}</p></div>{role!=="Student"&&<Button variant="primary" icon="plus" onClick={()=>navigate("Digital Library","Collections","New Collection")}>Create collection</Button>}</section><div className="submodule-strip library-menu">{menu.map(item=><button className={item===sub?"active":""} key={item} onClick={()=>navigate("Digital Library",item)}>{item}</button>)}</div><div className="library-search"><Icon name={sub==="AI Search"?"spark":"search"}/><input value={query} onChange={e=>{setQuery(e.target.value);setSearchConfirmed(false)}} onKeyDown={e=>e.key==="Enter"&&setSearchConfirmed(true)} placeholder={sub==="AI Search"?"Ask: What should I learn before SAP S/4HANA Finance?":"Search titles, technologies and resource types..."}/>{query&&<button onClick={()=>{setQuery("");setSearchConfirmed(false)}}><Icon name="close"/></button>}<Button variant="primary" onClick={()=>setSearchConfirmed(true)}>{searchConfirmed?`${visible.length} found`:sub==="AI Search"?"Ask AI":"Search"}</Button></div><div className="kpi-grid compact"><Kpi label="LEARNING RESOURCES" value="24,820" delta="Synthetic catalog" icon="trend"/><Kpi label="NEW THIS MONTH" value="1,240" delta="+2.4% this month" icon="check" color="cyan"/><Kpi label="CURRICULUM MAPPED" value="96%" delta="Verified metadata" icon="assessment" color="amber"/><Kpi label="SAVED" value={String(saved.length)} delta="Your library" icon="book" color="violet"/></div><section className="library-resource-grid">{visible.map((resource,index)=><article className="card" key={resource.title}><button className={`library-cover cover-${index%3===0?"math":index%3===1?"data":"physics"}`} onClick={()=>navigate("Digital Library",sub,resource.title)}><Icon name={resource.type==="Videos"?"play":resource.type==="Research"?"file":"book"} size={34}/><Badge>{resource.type.toUpperCase()}</Badge></button><div><Badge tone="ai">{resource.subject}</Badge><h2>{resource.title}</h2><p>{resource.meta}</p><div className="row-actions"><Button onClick={()=>setSaved(saved.includes(resource.title)?saved.filter(x=>x!==resource.title):[...saved,resource.title])}>{saved.includes(resource.title)?"Saved":"Save"}</Button><Button variant="primary" onClick={()=>navigate("Digital Library",sub,resource.title)}>Open</Button></div></div></article>)}</section>{!visible.length&&<section className="card course-empty"><Icon name="search" size={28}/><h2>No resources found</h2><p>Try another title, technology or resource type.</p><Button onClick={()=>setQuery("")}>Clear search</Button></section>}</div>;
}

