  const [tasks,setTasks]=useState<Record<string,boolean>>({"Review prerequisite notes":true,"Complete practice set":false,"Share one example":false});
  const menu=submodules.Collaboration;
  const action=()=>sub==="Messages"?navigate("Collaboration",sub,"New conversation"):sub==="Peer Learning"?setBooked(true):navigate("Collaboration",sub,`New ${sub.replace(/s$/,"")}`);
  if(detail?.startsWith("New ")) return <div className="page-stack"><WorkspaceBack title={detail} onBack={()=>navigate("Collaboration",sub)}/><section className="card collaboration-create"><div className="section-head"><div><span className="eyebrow">COLLABORATION SETUP</span><h2>{detail}</h2></div>{created&&<Badge tone="success">SAVED</Badge>}</div><div className="form-grid"><label>Title<input defaultValue={sub==="Messages"?"Message to learning group":`${sub} workspace`}/></label><label>Course or context<select><option>Mathematics Grade 10</option><option>Enterprise Java</option><option>Applied AI</option></select></label><label>Visibility<select><option>Invited members only</option><option>My class</option><option>Institution</option></select></label><label>Moderation<select><option>Teacher moderated</option><option>Member moderated</option></select></label></div><label className="assignment-long-field">Description<textarea defaultValue="A focused space to learn together, share evidence and coordinate the next steps."/></label><AudienceSelector label="Invite members"/><div className="panel-actions"><Button onClick={()=>setCreated(true)}>{created?"Draft saved":"Save draft"}</Button><Button variant="primary" icon="check" onClick={()=>setCreated(true)}>{created?"Created successfully":"Create & invite"}</Button></div></section></div>;
  if(detail) return <div className="page-stack"><WorkspaceBack title={detail} onBack={()=>navigate("Collaboration",sub)}/><div className="collaboration-detail-layout"><main className="card collaboration-room"><div className="section-head"><div><Badge tone="ai">{sub.toUpperCase()}</Badge><h2>{detail}</h2></div><Badge tone={joined?"success":"default"}>{joined?"JOINED":"ACTIVE"}</Badge></div><div className="collaboration-chat">{messages.map((text,index)=><div key={`${text}-${index}`}><Avatar initials={index%2?"ML":"AS"} tone={index}/><span><strong>{index%2?"Mei Lin":"Aarav Sharma"}</strong><p>{text}</p><small>{index+10}:4{index} AM</small></span></div>)}</div><div className="collaboration-composer"><input value={message} onChange={e=>setMessage(e.target.value)} onKeyDown={e=>{if(e.key==="Enter"&&message.trim()){setMessages([...messages,message]);setMessage("")}}} placeholder="Write a message or share an update..."/><Button icon="send" variant="primary" onClick={()=>{if(message.trim()){setMessages([...messages,message]);setMessage("")}}}>Send</Button></div></main><aside className="card collaboration-sidebar"><span className="eyebrow">WORKSPACE ACTIONS</span><Button variant={joined?"secondary":"primary"} className="full" onClick={()=>setJoined(!joined)}>{joined?"Leave workspace":"Join workspace"}</Button><Button className="full" icon="plus" onClick={()=>setMessages([...messages,"A new resource was shared with the group."])}>Share resource</Button><hr/><span className="eyebrow">SHARED TASKS</span>{Object.entries(tasks).map(([task,done])=><button className="collaboration-task" key={task} onClick={()=>setTasks({...tasks,[task]:!done})}><span className={done?"done":""}>{done&&<Icon name="check" size={12}/>}</span><strong>{task}</strong></button>)}<hr/><span className="eyebrow">PEER ACTIONS</span><button className="quick-link" onClick={()=>setLiked(!liked)}>{liked?"Helpful · recorded":"Mark as helpful"}<Icon name="check"/></button><button className="quick-link" onClick={()=>setBooked(true)}>{booked?"Session booked":"Book study session"}<Icon name="calendar"/></button></aside></div></div>;
