function AcademicManagementWorkspace({module,sub,detail,navigate}:{module:"Attendance"|"Gradebook"|"Credentials";sub:string;detail:string;navigate:(module:string,sub?:string,detail?:string)=>void}) {
  const [attendance,setAttendance]=useState<Record<string,boolean>>({"Aarav Sharma":true,"Sofia Martinez":true,"Noah Williams":false,"Mei Lin":true});
  const [saved,setSaved]=useState(false);
  const [approved,setApproved]=useState(false);
  const [reportGenerated,setReportGenerated]=useState(false);
  const [verificationId,setVerificationId]=useState("");
  const [verified,setVerified]=useState(false);
  const [scores,setScores]=useState<Record<string,string>>({"Aarav Sharma":"88","Sofia Martinez":"74","Noah Williams":"81","Mei Lin":"94"});
  const menu=submodules[module];
  const rows=academicManagementRows[sub==="Reports"?`${module} Reports`:sub]||academicManagementRows[module==="Attendance"?"Daily Attendance":module==="Gradebook"?"Grading Periods":"Certificates"];
  const description=module==="Attendance"?"Record attendance, review exceptions and coordinate fair follow-up.":module==="Gradebook"?"Manage grading structures, scores, moderation and academic reporting.":"Design, verify and issue evidence-backed certificates, badges and micro-credentials.";
  const createLabel=sub==="Reports"?"Generate report":sub==="Verification"?"Verify credential":sub==="Issuance"?"Issue credentials":`Create ${sub.replace(/s$/,"")}`;
  if(detail) return <div className="page-stack"><WorkspaceBack title={detail} onBack={()=>navigate(module,sub)}/><section className="card academic-detail"><div className="section-head"><div><Badge tone="ai">{module.toUpperCase()} · AUTHORIZED WORKSPACE</Badge><h2>{detail}</h2></div><Badge tone={approved?"success":"warning"}>{approved?"COMPLETED":"ACTION REQUIRED"}</Badge></div><div className="assessment-detail-summary">{[["Module",module],["Workspace",sub],["Owner","Authorized academic staff"],["Status",approved?"Completed":"Draft / review"]].map(([label,value])=><span key={label}><small>{label}</small><strong>{value}</strong></span>)}</div>{(detail.startsWith("Create ")||sub==="Issuance")&&<><div className="form-grid academic-detail-form"><label>Title<input defaultValue={detail.replace("Create ","")}/></label><label>Academic context<select><option>Institution-wide</option><option>Grade 10</option><option>Enterprise Learning</option></select></label><label>Effective date<input type="date" defaultValue="2025-06-08"/></label><label>Approval workflow<select><option>Academic office approval</option><option>Teacher approval</option></select></label></div><AudienceSelector label={module==="Credentials"?"Issue to":"Apply to"}/></>}<div className="ai-note"><Icon name="shield"/><p>Academic records require authorized review. Changes are recorded in the audit history before release.</p></div><div className="panel-actions"><Button onClick={()=>setSaved(true)}>{saved?"Draft saved":"Save draft"}</Button><Button variant={approved?"secondary":"primary"} icon="check" onClick={()=>setApproved(true)}>{approved?"Action completed":module==="Credentials"?"Approve & issue":"Approve & save"}</Button></div></section></div>;
  return <div className="page-stack"><section className="title-row"><div><Badge tone="ai">{module.toUpperCase()}</Badge><h1>{sub}</h1><p>{description}</p></div><Button variant="primary" icon={sub==="Reports"?"report":sub==="Verification"?"search":"plus"} onClick={()=>sub==="Reports"?setReportGenerated(true):sub==="Verification"?(()=>{setVerificationId("CRD-AI-2025-1042");setVerified(true)})():navigate(module,sub,sub==="Issuance"?"New credential issuance":`Create ${sub.replace(/s$/,"")}`)}>{reportGenerated?"Report generated":sub==="Verification"&&verified?"Credential verified":createLabel}</Button></section><div className="submodule-strip academic-menu">{menu.map(item=><button className={item===sub?"active":""} key={item} onClick={()=>navigate(module,item)}>{item}</button>)}</div><div className="kpi-grid compact"><Kpi label={module==="Attendance"?"PRESENT TODAY":module==="Gradebook"?"GRADED":"ISSUED"} value={module==="Attendance"?"92.8%":module==="Gradebook"?"86%":"1,842"} delta="Current academic period" icon="check"/><Kpi label="NEEDS REVIEW" value={module==="Credentials"?"24":"12"} delta="Authorized action" icon="warning" color="amber"/><Kpi label={module==="Credentials"?"VERIFIED":"COMPLETION"} value={module==="Credentials"?"98.6%":"94%"} delta="+2.4% this month" icon="trend" color="cyan"/><Kpi label="ACTIVE RECORDS" value="42" delta="Live sample data" icon="file" color="violet"/></div>
    {module==="Attendance"&&(sub==="Daily Attendance"||sub==="Class Attendance")&&<section className="card academic-register"><div className="section-head"><div><span className="eyebrow">ATTENDANCE REGISTER</span><h2>{sub==="Daily Attendance"?"Grade 10A · Morning register":"Mathematics Grade 10A"}</h2></div><Badge tone={saved?"success":"default"}>{saved?"SAVED":"EDITING"}</Badge></div>{Object.entries(attendance).map(([name,present],index)=><button key={name} onClick={()=>{setAttendance({...attendance,[name]:!present});setSaved(false)}}><Avatar initials={name.split(" ").map(x=>x[0]).join("")} tone={index}/><span><strong>{name}</strong><small>STU-2025-{1042+index}</small></span><Badge tone={present?"success":"warning"}>{present?"PRESENT":"ABSENT"}</Badge></button>)}<div className="panel-actions"><Button onClick={()=>setAttendance(Object.fromEntries(Object.keys(attendance).map(name=>[name,true])))}>Mark all present</Button><Button variant="primary" icon="check" onClick={()=>setSaved(true)}>{saved?"Attendance saved":"Save register"}</Button></div></section>}
    {module==="Gradebook"&&sub==="Gradebook"&&<section className="card gradebook-register"><div className="section-head"><div><span className="eyebrow">GRADE ENTRY</span><h2>Mathematics Grade 10 · Term 2</h2></div><Badge tone={saved?"success":"default"}>{saved?"PUBLISHED":"DRAFT"}</Badge></div><div className="gradebook-row head"><span>Learner</span><span>Assignment</span><span>Assessment</span><span>Final score</span><span>Status</span></div>{Object.entries(scores).map(([name,score],index)=><div className="gradebook-row" key={name}><span><Avatar initials={name.split(" ").map(x=>x[0]).join("")} tone={index}/><strong>{name}</strong></span><span>84%</span><span>92%</span><input value={score} onChange={e=>{setScores({...scores,[name]:e.target.value});setSaved(false)}}/><Badge tone={Number(score)>=80?"success":"warning"}>{Number(score)>=80?"ON TRACK":"REVIEW"}</Badge></div>)}<div className="panel-actions"><Button onClick={()=>setSaved(true)}>Save draft</Button><Button variant="primary" icon="check" onClick={()=>setSaved(true)}>{saved?"Grades published":"Publish grades"}</Button></div></section>}
    {module==="Credentials"&&sub==="Verification"&&<section className="card credential-verification"><div className="section-head"><div><span className="eyebrow">PUBLIC VERIFICATION</span><h2>Verify credential authenticity</h2></div>{verified&&<Badge tone="success">VERIFIED</Badge>}</div><div className="verification-search"><Icon name="credential"/><input value={verificationId} onChange={e=>{setVerificationId(e.target.value);setVerified(false)}} placeholder="Enter credential ID, learner ID or verification URL"/><Button variant="primary" onClick={()=>setVerified(Boolean(verificationId.trim()))}>Verify</Button></div>{verified&&<div className="verified-credential"><Icon name="check" size={26}/><span><small>VALID CREDENTIAL</small><h2>Applied AI Foundations</h2><p>Issued to Aarav Sharma · June 2025 · Northstar International School</p></span><Badge tone="success">AUTHENTIC</Badge></div>}</section>}
    {!((module==="Attendance"&&(sub==="Daily Attendance"||sub==="Class Attendance"))||(module==="Gradebook"&&sub==="Gradebook")||(module==="Credentials"&&sub==="Verification"))&&<section className="card academic-list"><div className="section-head"><div><span className="eyebrow">{sub.toUpperCase()} WORKSPACE</span><h2>Current records and actions</h2></div><Button icon="report" onClick={()=>setReportGenerated(true)}>{reportGenerated?"Generated":"Export"}</Button></div>{rows.map(([title,context,signal,status],index)=><button key={title} onClick={()=>navigate(module,sub,title)}><span className={`list-icon tone-${index%2?"violet":"blue"}`}><Icon name={module==="Attendance"?"check":module==="Gradebook"?"grade":"credential"}/></span><span><small>{context.toUpperCase()}</small><strong>{title}</strong><em>{signal}</em></span><Badge tone={status.match(/approved|published|active|ready|resolved|recorded/i)?"success":status.match(/review|pending/i)?"warning":"default"}>{status}</Badge><Icon name="chevron"/></button>)}</section>}
  </div>;
}

