function CoordinatorScores({detail,navigate}:{detail:string;navigate:(module:string,sub?:string,detail?:string)=>void}) {
  const [score,setScore]=useState(78);
  const [reason,setReason]=useState("");
  const [saved,setSaved]=useState(false);
  const [submitted,setSubmitted]=useState(false);
  const [published,setPublished]=useState(false);
  if(detail==="Final Scoresheet") {
    const rows=[["STU-1042","Aarav Sharma","86","834","82","88","84","94.2"],["STU-1188","Sofia Martinez","78","760","74","81","79","88.6"],["STU-1096","Noah Williams","72","690","68","76","71","74.2"],["STU-1241","Mei Lin","94","980","91","93","92","97.6"]];
    return <div className="page-stack"><WorkspaceBack title="Assessment Scores" onBack={()=>navigate("Assessments","Results")}/><section className="title-row"><div><Badge tone="ai">FINAL SCORESHEET BUILDER · OA-24</Badge><h1>Oracle Applications Final Results</h1><p>Configure weightages, validate eligibility and submit for controlled publication.</p></div><Badge tone={published?"success":submitted?"warning":"default"}>{published?"PUBLISHED":submitted?"AWAITING APPROVAL":"DRAFT"}</Badge></section><section className="card weightage-panel"><div className="section-head"><div><span className="eyebrow">GRADING RULES</span><h2>Configurable weightages</h2></div><Badge tone="success">TOTAL 100%</Badge></div>{[["Quiz scores","10%"],["Quick Quest","10%"],["Assignments","20%"],["Practical","20%"],["Final examination","40%"]].map(([label,value])=><label key={label}>{label}<input defaultValue={value}/></label>)}<span><small>Minimum passing mark</small><strong>60%</strong></span><span><small>Attendance eligibility</small><strong>75%</strong></span></section><section className="card scoresheet-table"><div className="scoresheet-row head"><span>ID / Student</span><span>Quiz</span><span>Quest</span><span>Assign.</span><span>Practical</span><span>Final</span><span>Attend.</span><span>Total</span><span>Grade</span><span>Status</span></div>{rows.map(([id,name,quiz,quest,assignment,practical,final,attendance],i)=>{const total=Math.round(+quiz*.1+(+quest/10)*.1+ +assignment*.2+ +practical*.2+ +final*.4);const eligible=+attendance>=75;return <div className="scoresheet-row" key={id}><span><strong>{name}</strong><small>{id}</small></span><span>{quiz}</span><span>{quest}</span><span>{assignment}</span><span>{practical}</span><span>{final}</span><span>{attendance}%</span><strong>{total}%</strong><Badge>{total>=85?"A":total>=70?"B":"C"}</Badge><Badge tone={eligible&&total>=60?"success":"danger"}>{eligible&&total>=60?"PASS":"REVIEW"}</Badge></div>})}</section><div className="scoresheet-actions"><Button icon="warning">Validate missing marks</Button><Button icon="file">Export Excel</Button><Button icon="report">Export PDF</Button><Button>Print</Button><Button variant="primary" onClick={()=>submitted?setPublished(true):setSubmitted(true)}>{published?"Results published":submitted?"Approve & publish":"Submit for approval"}</Button></div></div>;
  }
  return <div className="page-stack"><section className="title-row"><div><Badge tone="ai">COORDINATOR · AUDITED MARKS</Badge><h1>Assessment Score Management</h1><p>Review quiz, exam, assignment and game scores for assigned batches.</p></div><div className="row-actions"><Button icon="file">Import marks</Button><Button variant="primary" icon="grade" onClick={()=>navigate("Assessments","Results","Final Scoresheet")}>Generate final scoresheet</Button></div></section><div className="kpi-grid compact"><Kpi label="SCORES RECEIVED" value="324" delta="Across 3 batches" icon="assessment"/><Kpi label="MISSING MARKS" value="8" delta="Validation required" icon="warning" color="amber"/><Kpi label="AI RESULTS" value="86" delta="Awaiting verification" icon="spark" color="violet"/><Kpi label="VERIFIED" value="92%" delta="+12% this week" icon="check" color="cyan"/></div><section className="card coordinator-table"><div className="section-head"><div><span className="eyebrow">OA-24 · ORACLE SQL KNOWLEDGE CHECK</span><h2>Marks verification</h2></div><Badge>MAXIMUM 100</Badge></div><div className="score-grid-row head"><span>Student</span><span>Source</span><span>Original</span><span>Modified</span><span>Status</span><span/></div>{[["Aarav Sharma","AI assessed","86","Verified"],["Sofia Martinez","Teacher entered","78","Review"],["Noah Williams","Import","—","Missing"],["Mei Lin","AI assessed","94","Verified"]].map(([name,source,value,status],i)=><div className="score-grid-row" key={name}><span className="student-cell"><Avatar initials={name.split(" ").map(x=>x[0]).join("")} tone={i}/><strong>{name}</strong></span><span>{source}</span><span>{value}</span><input type="number" min="0" max="100" value={i===1?score:value==="—"?"":value} onChange={e=>i===1&&setScore(Math.min(100,Math.max(0,+e.target.value)))}/><Badge tone={status==="Verified"?"success":status==="Missing"?"danger":"warning"}>{status}</Badge><button onClick={()=>setSaved(false)}><Icon name="chevron"/></button></div>)}</section><section className="card score-audit-editor"><div><span className="eyebrow">AUDITED SCORE CHANGE</span><h2>Sofia Martinez · 78 → {score}</h2><p>Every modification retains original value, editor, timestamp and mandatory reason.</p></div><label>Reason for modification<input value={reason} onChange={e=>setReason(e.target.value)} placeholder="Enter a required reason..."/></label><Button variant="primary" onClick={()=>reason.trim()&&setSaved(true)}>{saved?"Change recorded":"Save audited change"}</Button></section></div>;
}

