function SignupScreen({onBack,onRegistered,fontScale,onFontScale}:{onBack:()=>void;onRegistered:(role:Role,institution:string,session:Session)=>void;fontScale:FontScale;onFontScale:(scale:FontScale)=>void}) {
  const [step,setStep]=useState(1);
  const [accountType,setAccountType]=useState<Role>("Student");
  const [tenantMode,setTenantMode]=useState<"join"|"create">("join");
  const [institution,setInstitution]=useState("Northstar International School");
  const [institutionName,setInstitutionName]=useState("");
  const [inviteCode,setInviteCode]=useState("");
  const [firstName,setFirstName]=useState("");
  const [lastName,setLastName]=useState("");
  const [email,setEmail]=useState("");
  const [password,setPassword]=useState("");
  const [consent,setConsent]=useState(false);
  const [busy,setBusy]=useState(false);
  const [error,setError]=useState("");
  const next=()=>{if(step===1&&tenantMode==="create"&&!institutionName.trim()){setError("Enter your institution name to continue.");return}if(step===1&&tenantMode==="join"&&!inviteCode.trim()){setError("Enter the invitation or institution code.");return}if(step===2&&(!firstName.trim()||!lastName.trim()||!email.includes("@")||password.length<8||!/\d/.test(password)||!/[A-Z]/.test(password))){setError("Complete all fields using a valid email and a password of at least 8 characters, with one number and one uppercase letter.");return}setError("");setStep(Math.min(3,step+1))};
  const finish=async()=>{if(busy)return;if(!consent){setError("Accept the privacy notice and platform terms to create the account.");return}setBusy(true);setError("");try{const session=await registerAccount({email,password,first_name:firstName.trim(),last_name:lastName.trim(),role:accountType,institution_name:tenantMode==="create"?institutionName.trim():institution,create_institution:tenantMode==="create"});onRegistered(mapBackendRole(session.roles),session.institution_name,session)}catch(err){setError(err instanceof Error?err.message:"Account creation failed.")}finally{setBusy(false)}};
  return <main className="login-shell"><AuthShowcase mode="signup"/><section className="login-access-panel"><div className="login-card signup-card"><div className="auth-font-row"><button className="auth-back" onClick={onBack}><Icon name="arrow"/> Back to sign in</button><FontSizeControl scale={fontScale} onChange={onFontScale}/></div><div className="login-heading"><span className="login-lock"><Icon name={step===1?"admin":step===2?"student":"check"}/></span><div><Badge>NEW USER REGISTRATION · STEP {step} OF 3</Badge><h2>{step===1?"Choose your workspace":step===2?"Create your profile":"Review and confirm"}</h2><p>{step===1?"Connect to an institution or create a tenant.":step===2?"Provide the details used for your learning identity.":"Confirm your access request and privacy choices."}</p></div></div>{step===1&&<><div className="tenant-mode"><button className={tenantMode==="join"?"active":""} onClick={()=>setTenantMode("join")}><Icon name="people"/><span><strong>Join an institution</strong><small>Use an invitation or institution code</small></span></button><button className={tenantMode==="create"?"active":""} onClick={()=>{setTenantMode("create");setAccountType("Administrator")}}><Icon name="admin"/><span><strong>Create a workspace</strong><small>For institution administrators</small></span></button></div>{tenantMode==="join"?<><label className="login-field">Institution<div className="login-select"><Icon name="admin"/><select value={institution} onChange={e=>setInstitution(e.target.value)}><option>Northstar International School</option><option>Meridian College of Technology</option><option>Horizon Global University</option></select><Icon name="chevron" size={14}/></div></label><label className="login-field">Invitation or institution code<div className="login-input"><Icon name="credential"/><input value={inviteCode} onChange={e=>setInviteCode(e.target.value)} placeholder="Example: EDU-2025-1042"/></div></label></>:<><label className="login-field">Institution or organization name<div className="login-input"><Icon name="admin"/><input value={institutionName} onChange={e=>setInstitutionName(e.target.value)} placeholder="Enter legal institution name"/></div></label><label className="login-field">Institution type<div className="login-select"><Icon name="library"/><select><option>K–12 School</option><option>College</option><option>University</option><option>Coaching Institute</option><option>Enterprise Learning</option></select><Icon name="chevron" size={14}/></div></label></>}<label className="login-field">I am registering as<div className="signup-role-grid">{(Object.keys(roleProfiles) as Role[]).map((r,i)=><button className={accountType===r?"active":""} key={r} onClick={()=>setAccountType(r)} disabled={tenantMode==="create"&&r!=="Administrator"}><Icon name={roleProfiles[r].icon}/><span>{r}</span></button>)}</div></label></>}{step===2&&<div className="signup-profile"><div className="form-grid"><label className="login-field">First name<div className="login-input"><Icon name="student"/><input value={firstName} onChange={e=>setFirstName(e.target.value)} placeholder="First name"/></div></label><label className="login-field">Last name<div className="login-input"><Icon name="student"/><input value={lastName} onChange={e=>setLastName(e.target.value)} placeholder="Last name"/></div></label></div><label className="login-field">Institution email<div className="login-input"><Icon name="chat"/><input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="name@institution.edu"/></div></label><label className="login-field">Create password<div className="login-input"><Icon name="shield"/><input type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="At least 8 characters"/></div></label><div className="password-rules">{[["8+ characters",password.length>=8],["One number",/\d/.test(password)],["One uppercase",/[A-Z]/.test(password)]].map(([label,ok])=><span className={ok?"valid":""} key={label as string}><Icon name={ok?"check":"clock"} size={12}/>{label as string}</span>)}</div></div>}{step===3&&<div className="signup-review"><div className="signup-review-person"><Avatar initials={`${firstName[0]||"N"}${lastName[0]||"U"}`} tone={2} large/><span><Badge tone="success">READY TO CREATE</Badge><h2>{firstName} {lastName}</h2><p>{email}</p></span></div>{[["Institution",tenantMode==="create"?institutionName:institution],["Account type",accountType],["Access status",tenantMode==="create"?"Administrator onboarding":"Pending institution verification"],["Data region","India · Mumbai"]].map(([label,value])=><span className="signup-review-row" key={label}><small>{label}</small><strong>{value}</strong></span>)}<label className="signup-consent"><input type="checkbox" checked={consent} onChange={e=>setConsent(e.target.checked)}/><span>I agree to the platform terms and acknowledge the privacy notice. My institution may review and approve this access request.</span></label><div className="login-security-note"><Icon name="shield"/><p>This email and password are saved. Sign out and sign in again with the same email and password.</p></div></div>}{error&&<div className="signup-error"><Icon name="warning"/>{error}</div>}<div className="signup-actions">{step>1&&<Button onClick={()=>{setStep(step-1);setError("")}}>Previous</Button>}<Button variant="primary" onClick={step===3?finish:next}>{busy?"Creating account...":step===3?"Create account":"Continue"} <Icon name="chevron" size={14}/></Button></div></div><footer className="login-footer"><span>© 2025 IntelUniVen Software Solutions Pvt. Ltd.</span><button>Privacy</button><button>Terms</button><button>Help</button></footer></section></main>;
}

function LoginScreen({onLogin,onSignup,onPrototype,fontScale,onFontScale}:{onLogin:(role:Role,institution:string,session:Session)=>void|Promise<void>;onSignup:()=>void;onPrototype:(role:Role,institution:string)=>void;fontScale:FontScale;onFontScale:(scale:FontScale)=>void}) {
  const tenants=["Northstar International School","Meridian College of Technology","Horizon Global University"];
  const accounts=(Object.entries(roleProfiles) as [Role,typeof roleProfiles[Role]][]).map(([role,profile])=>({...profile,role}));
  const [tenant,setTenant]=useState(tenants[0]);
  const [account,setAccount]=useState(0);
  const [method,setMethod]=useState<"password"|"otp"|"sso">("password");
  const [email,setEmail]=useState(accounts[0].email);
  const [password,setPassword]=useState("Demo@2025");
  const [otpSent,setOtpSent]=useState(false);
  const [otp,setOtp]=useState("");
  const [busy,setBusy]=useState(false);
  const [error,setError]=useState("");
  const selected=accounts[account];
  const selectAccount=(i:number)=>{setAccount(i);setEmail(accounts[i].email);setOtpSent(false);setOtp("")};
  const signIn=async()=>{
    setBusy(true);
    setError("");
    try{
      const session=await demoLogin(email,password);
      await onLogin(mapBackendRole(session.roles),session.institution_name,session);
    }catch(err){
      setError(err instanceof Error?err.message:"Sign-in failed. The API is not available.");
    }finally{
      setBusy(false);
    }
  };
  return <main className="login-shell"><AuthShowcase mode="login"/><section className="login-access-panel"><div className="login-card"><div className="auth-font-row"><FontSizeControl scale={fontScale} onChange={onFontScale}/></div><div className="login-heading"><span className="login-lock"><Icon name="shield"/></span><div><Badge>INTELUNIVEN AI EDU LAB · DEMO ACCESS</Badge><h2>Welcome back</h2><p>Select your institution and account to continue.</p></div></div><label className="login-field">Institution workspace<div className="login-select"><span><Icon name="admin"/></span><select value={tenant} onChange={e=>setTenant(e.target.value)}>{tenants.map(x=><option key={x}>{x}</option>)}</select><Icon name="chevron" size={14}/></div></label><div className="login-divider"><span>Choose a demo identity</span></div><div className="login-accounts">{accounts.map((profile,i)=><button className={account===i?"active":""} key={profile.email} onClick={()=>selectAccount(i)}><Avatar initials={profile.initials} tone={i}/><span><strong>{profile.name}</strong><small>{profile.role} · {profile.label}</small></span>{account===i?<Icon name="check"/>:<Icon name={profile.icon}/>}</button>)}</div><div className="login-methods">{([["password","Password"],["otp","Email OTP"],["sso","Institution SSO"]] as const).map(([key,label])=><button className={method===key?"active":""} key={key} onClick={()=>{setMethod(key);setOtpSent(false)}}>{label}</button>)}</div>{method==="password"&&<div className="login-form"><label className="login-field">Email address<div className="login-input"><Icon name="student"/><input value={email} onChange={e=>setEmail(e.target.value)} placeholder="name@institution.edu"/></div></label><label className="login-field">Password<div className="login-input"><Icon name="shield"/><input type="password" value={password} onChange={e=>setPassword(e.target.value)} onKeyDown={e=>e.key==="Enter"&&signIn()} placeholder="Enter password"/></div></label><button className="forgot-link">Forgot password?</button><Button variant="primary" className="full" onClick={signIn}>{busy?"Signing in...":"Sign in securely"} <Icon name="chevron" size={14}/></Button></div>}{method==="otp"&&<div className="login-form"><label className="login-field">Institution email<div className="login-input"><Icon name="student"/><input value={email} onChange={e=>setEmail(e.target.value)} placeholder="name@institution.edu"/></div></label>{otpSent&&<label className="login-field">Six-digit verification code<div className="login-input otp-input"><Icon name="shield"/><input value={otp} onChange={e=>setOtp(e.target.value)} placeholder="000 000"/></div></label>}<Button variant="primary" className="full" onClick={()=>otpSent?signIn():setOtpSent(true)}>{otpSent?"Verify & continue":"Send one-time code"}</Button>{otpSent&&<small className="otp-note"><Icon name="check" size={13}/> Demo verification code sent. Any value continues in prototype mode.</small>}</div>}{method==="sso"&&<div className="sso-panel"><BrandLogo compact/><h2>Continue with institution SSO</h2><p>You will be redirected to {tenant}'s identity provider.</p><Button variant="primary" className="full" onClick={signIn}>Continue with SSO <Icon name="chevron" size={14}/></Button></div>}{error&&<div className="signup-error"><Icon name="warning"/>{error}</div>}{error&&<Button className="full" onClick={()=>onPrototype(selected.role,tenant)}>Continue in prototype mode</Button>}<div className="new-user-callout"><span><strong>New to IntelUniVen AI Edu Lab?</strong><small>Create a learner, faculty, guardian or institution account.</small></span><Button icon="plus" onClick={onSignup}>Create account</Button></div><div className="login-security-note"><Icon name="shield"/><p><strong>Live demo login</strong> uses the FastAPI demo JWT (password Demo@2025). OTP and SSO remain prototype-only. If the API is down, continue in prototype mode without claiming a trusted session.</p></div></div><footer className="login-footer"><span>© 2025 IntelUniVen Software Solutions Pvt. Ltd.</span><button>Privacy</button><button>Security</button><button>Help</button></footer></section></main>;
}

export default function App() {
  const [authenticated,setAuthenticated]=useState(false);
  const [authView,setAuthView]=useState<"login"|"signup">("login");
  const [liveSession,setLiveSession]=useState<Session|null>(null);
  const [role,setRole]=useState<Role>("Student");
  const [institution,setInstitution]=useState("Northstar International School");
  const [module,setModule]=useState("Dashboard");
  const [sub,setSub]=useState("My Dashboard");
  const [detail,setDetail]=useState("");
  const [sidebar,setSidebar]=useState(true);
  const [copilot,setCopilot]=useState(false);
  const [search,setSearch]=useState(false);
  const [roleMenu,setRoleMenu]=useState(false);
  const [mobileNav,setMobileNav]=useState(false);
  const [fontScale,setFontScale]=useState<FontScale>(()=>{const scale=readFontScale();document.documentElement.dataset.fontScale=scale;return scale});
  useEffect(()=>{document.documentElement.dataset.fontScale=fontScale;try{localStorage.setItem(fontScaleKey,fontScale)}catch{/* ignore storage failures */}},[fontScale]);
  const navigate=(m:string,s?:string,d?:string)=>{setModule(m);setSub(s||submodules[m]?.[0]||m);setDetail(d||"");setMobileNav(false);window.scrollTo({top:0,behavior:"smooth"})};
  const allowedModules=useMemo(()=>new Set(visibleModules(role,liveSession?.roles??[])),[role,liveSession]);
  const visibleNav=useMemo(()=>navSections.map(section=>({...section,items:section.items.filter(([name])=>allowedModules.has(name))})).filter(x=>x.items.length),[allowedModules]);
  const profile=roleProfiles[role];
  const canCreate=role==="Teacher / Faculty"||role==="Administrator";
  const searchSuggestions=role==="Student"
    ? [["Continue my Oracle SQL training","Courses","book"],["Show my upcoming assignments","Assignments","assignment"],["Open my attendance report","Attendance","check"]]
    : role==="Training Coordinator"
      ? [["Open my assigned batch scoresheets","Assessments","assessment"],["Show OA-24 assessment results","Assessments","grade"],["View my authorized batch schedule","Calendar","calendar"]]
      : role==="Parent / Guardian / HOD"
        ? [["Show Aarav's progress","Student Success","trend"],["Open Aarav's attendance","Attendance","check"],["View linked learner reports","Analytics","report"]]
        : role==="Principal / L&D Lead"
          ? [["Compare authorized training batches","Analytics","chart"],["Show institution attendance trends","Analytics","check"],["Open training outcomes report","Reports","report"]]
          : [["Show learners needing attention","Student Information","student"],["Find courses with declining engagement","Analytics","chart"],["Open the latest performance report","Reports","report"]];
  useEffect(()=>{
    const stored=loadStoredSession();
    if(!stored) return;
    setLiveSession(stored);
    setRole(mapBackendRole(stored.roles));
    setInstitution(stored.institution_name);
    setAuthenticated(true);
  },[]);
  const enterPlatform=(nextRole:Role,nextInstitution:string,nextSession?:Session|null)=>{setRole(nextRole);setInstitution(nextInstitution);setLiveSession(nextSession??loadStoredSession());setAuthenticated(true);setAuthView("login");setModule("Dashboard");setSub("My Dashboard")};
  const enterLive=(nextRole:Role,nextInstitution:string,session:Session)=>{setLiveSession(session);enterPlatform(nextRole,nextInstitution)};
  const enterPrototype=(nextRole:Role,nextInstitution:string)=>{clearToken();setLiveSession(null);enterPlatform(nextRole,nextInstitution)};
  if(!authenticated) return authView==="signup"?<SignupScreen onBack={()=>setAuthView("login")} onRegistered={enterLive} fontScale={fontScale} onFontScale={setFontScale}/>:<LoginScreen onSignup={()=>setAuthView("signup")} onLogin={enterLive} onPrototype={enterPrototype} fontScale={fontScale} onFontScale={setFontScale}/>;
  const contextPrompt=module==="AI Study Buddy"?"Explain quadratic equations.":module==="Adaptive Learning"?"Why did difficulty increase?":module==="Student Success"?"Summarize the evidence behind this student's academic-risk flag.":module==="Assignments"?"Summarize the assignment items that need teacher review.":module==="Assessments"&&sub==="Proctoring"?"Summarize integrity signals that require human review.":module==="Gamification"?"Recommend a healthy DQ learning experience and explain why.":module==="Data Security & Privacy"?"Summarize tenant isolation and privacy policy exceptions.":module==="Courses"?"Create a quiz from Module 3":module==="Analytics"?"Why is student engagement declining?":module==="Student Information"?"Summarize this learner's progress":module==="Administration"?"Show institutions with declining usage":`Help me with ${module}`;
  const live=Boolean(liveSession&&getStoredToken());
  let content:React.ReactNode;
  if(module==="Dashboard") content=<Dashboard role={role} navigate={navigate}/>;
  else if(module==="Courses"&&!detail) content=<Courses navigate={navigate} role={role}/>;
  else if(module==="Courses"&&detail.startsWith("lesson")) content=<Lesson detail={detail} navigate={navigate}/>;
  else if(module==="Courses"&&detail&&detail!=="builder") content=<CourseDetail title={detail} navigate={navigate}/>;
  else if(module==="Courses"&&detail==="builder") content=<CourseBuilder/>;
  else if(module==="Virtual Classroom") content=<VirtualClassroomWorkspace sub={sub} detail={detail} navigate={navigate} role={role}/>;
  else if(module==="Digital Library") content=<DigitalLibraryWorkspace sub={sub} detail={detail} navigate={navigate} role={role}/>;
  else if(module==="Collaboration") content=<CollaborationWorkspace sub={sub} detail={detail} navigate={navigate}/>;
  else if(module==="Communication") content=<CommunicationWorkspace sub={sub} detail={detail} navigate={navigate}/>;
  else if(live&&role==="Training Coordinator"&&module==="Attendance") content=<LiveAttendance/>;
  else if(role==="Training Coordinator"&&module==="Attendance") content=<CoordinatorAttendance detail={detail} navigate={navigate}/>;
  else if(live&&(role==="Student"||role==="Parent / Guardian / HOD")&&(module==="Attendance"||module==="Gradebook")) content=<LivePersonalRecord module={module} parent={role==="Parent / Guardian / HOD"}/>;
  else if((role==="Student"||role==="Parent / Guardian / HOD")&&(module==="Attendance"||module==="Gradebook"||module==="Credentials")) content=<PersonalAcademicRecord module={module} role={role}/>;
  else if(live&&module==="Attendance") content=<LiveAttendance/>;
  else if(live&&module==="Gradebook") content=<LiveRoster variant="gradebook"/>;
  else if(module==="Attendance"||module==="Gradebook"||module==="Credentials") content=<AcademicManagementWorkspace module={module} sub={sub} detail={detail} navigate={navigate}/>;
  else if(module==="Integrations") content=<IntegrationsWorkspace sub={sub} detail={detail} navigate={navigate}/>;
  else if(module==="Learning Intelligence"&&detail) content=<ModelWorkspace model={detail} navigate={navigate}/>;
  else if(module==="Learning Intelligence"&&sub==="Learning Models") content=<LearningModelCatalog navigate={navigate}/>;
  else if(module==="Learning Intelligence"&&sub==="AI Learning Orchestrator") content=<LearningOrchestrator/>;
  else if(module==="Learning Intelligence"&&sub==="Personalization Engine") content=<PersonalizationEngine/>;
  else if(module==="Learning Intelligence"&&sub==="Learning Journey Designer") content=<JourneyDesigner/>;
  else if(module==="Learning Intelligence"&&sub==="Model Analytics") content=<ModelAnalytics/>;
  else if(module==="Learning Intelligence") content=<IntelligenceCommandCenter navigate={navigate}/>;
  else if(module==="Learning Paths"&&sub==="My Learning Path"&&!detail) content=<LearningPathWorkspace navigate={navigate} moduleName="Learning Paths"/>;
  else if(module==="Learning Paths"&&sub==="My Learning Path"&&detail) content=<LearningPathDetail detail={detail} navigate={navigate} moduleName="Learning Paths"/>;
  else if(module==="Learning Paths") content=<AdaptiveDeepDive sub={sub} detail={detail} navigate={navigate}/>;
  else if(module==="AI & Personalization") content=<AIPersonalizationCommandCenter navigate={navigate}/>;
  else if(module==="AI Study Buddy"&&sub==="Ask AI"&&!detail) content=<StudyBuddy navigate={navigate}/>;
  else if(module==="AI Study Buddy"&&sub==="Ask AI"&&detail) content=<StudyActionDetail sub="Ask AI" detail={detail} navigate={navigate}/>;
  else if(module==="AI Study Buddy") content=<StudyFunctionWorkspace sub={sub} detail={detail} navigate={navigate}/>;
  else if(module==="Adaptive Learning") content=<AdaptiveDeepDive sub={sub} detail={detail} navigate={navigate}/>;
  else if(live&&module==="Student Information"&&role==="Training Coordinator") content=<LiveRoster variant="batch"/>;
  else if(module==="Student Information"&&role==="Training Coordinator") content=<CoordinatorBatchManagement navigate={navigate}/>;
  else if(module==="Student Information"&&!detail) content=<StudentInfo navigate={navigate}/>;
  else if(module==="Student Information"&&detail) content=<Student360 name={detail} navigate={navigate}/>;
  else if(module==="Student Success") content=<StudentSuccessDeepDive sub={sub} detail={detail} navigate={navigate}/>;
  else if(live&&module==="Assignments"&&(role==="Student"||role==="Teacher / Faculty"||role==="Training Coordinator"||role==="Administrator")) content=<LiveAssignments/>;
  else if(module==="Assignments"&&role==="Student") content=<StudentAssignmentHub detail={detail} navigate={navigate}/>;
  else if(module==="Assignments") content=<AssignmentsDeepDive sub={sub} detail={detail} navigate={navigate}/>;
  else if(module==="Gamification") content=<GamificationDeepDive sub={sub} detail={detail} navigate={navigate} role={role}/>;
  else if(module==="Data Security & Privacy") content=<DataSecurityPrivacy sub={sub}/>;
  else if(module==="Assessments"&&role==="Student") content=<StudentExamCenter navigate={navigate}/>;
  else if(live&&module==="Assessments"&&sub==="Proctoring") content=<LiveProctoring/>;
  else if(live&&module==="Assessments"&&role==="Training Coordinator") content=<LiveScores/>;
  else if(live&&module==="Assessments"&&(sub==="Quiz Builder"||sub==="Question Bank")&&(role==="Teacher / Faculty"||role==="Administrator")) content=<LiveQuestionBank/>;
  else if(module==="Assessments"&&role==="Training Coordinator"&&sub==="Proctoring") content=<AssessmentProctoring detail={detail} navigate={navigate}/>;
  else if(module==="Assessments"&&role==="Training Coordinator") content=<CoordinatorScores detail={detail} navigate={navigate}/>;
  else if(module==="Assessments"&&sub==="Proctoring") content=<AssessmentProctoring detail={detail} navigate={navigate}/>;
  else if(module==="Assessments"&&sub==="Assessments") content=<Assessments mode="assessment"/>;
  else if(module==="Assessments"&&sub==="Quiz Builder") content=<Assessments mode="quiz"/>;
  else if(module==="Assessments") content=<AssessmentSectionWorkspace sub={sub} detail={detail} navigate={navigate}/>;
  else if(live&&module==="Analytics"&&(role==="Principal / L&D Lead"||role==="Administrator")) content=<><LiveCompletionReport/><AnalyticsWorkspace sub={sub} detail={detail} navigate={navigate}/></>;
  else if(module==="Analytics") content=<AnalyticsWorkspace sub={sub} detail={detail} navigate={navigate}/>;
  else if(live&&module==="Administration"&&sub==="Billing") content=<LiveBilling/>;
  else if(module==="Calendar") content=<TrainingCalendar role={role}/>;
  else content=<GenericWorkspace module={module} sub={sub} detail={detail} navigate={navigate}/>;
  return <div className={`app ${sidebar?"":"sidebar-collapsed"} ${copilot?"copilot-open":""}`}>
    <aside className={`sidebar ${mobileNav?"mobile-open":""}`}>
      <div className="brand"><BrandLogo compact/>{sidebar&&<div><strong>IntelUniVen <em>AI</em></strong><small>EDU LAB</small></div>}<button className="collapse-btn" onClick={()=>setSidebar(!sidebar)}><Icon name={sidebar?"arrow":"chevron"}/></button></div>
      <div className="nav-scroll">{visibleNav.map(section=><div className="nav-section" key={section.label}><span className="nav-label">{sidebar?section.label:""}</span>{section.items.map(([name,icon])=><button className={module===name?"active":""} key={name} onClick={()=>navigate(name)} title={name}><Icon name={icon as IconName}/>{sidebar&&<span>{name}</span>}{module===name&&sidebar&&<i/>}</button>)}</div>)}</div>
      <div className="sidebar-footer"><button onClick={()=>setCopilot(true)}><span className="ai-nav-icon"><Icon name="spark"/></span>{sidebar&&<span><strong>IntelUniVen AI Copilot</strong><small>by IntelUniVen</small></span>}</button><div className="platform-status"><i/>{sidebar&&<span>© IntelUniVen Software Solutions Pvt. Ltd.</span>}</div></div>
    </aside>
    <div className="app-body">
      <header className="topbar"><button className="mobile-menu" onClick={()=>setMobileNav(!mobileNav)}><Icon name="menu"/></button><button className="institution"><span className="institution-logo">{institution.includes("School")?"BI":institution.includes("College")?"BC":"BU"}</span><span><small>Institution</small><strong>{institution}</strong></span><Icon name="chevron" size={14}/></button><button className="global-search" onClick={()=>setSearch(true)}><Icon name="search"/><span>{role==="Student"?"Search my courses, lessons and work...":"Search within your authorized scope..."}</span><kbd>⌘ K</kbd></button><div className="top-actions"><FontSizeControl scale={fontScale} onChange={setFontScale}/><Button variant="ghost" icon="spark" onClick={()=>setCopilot(!copilot)}>AI Copilot</Button>{canCreate&&<Button variant="primary" icon="plus">Quick create</Button>}<button className="icon-btn"><Icon name="chat"/></button><button className="icon-btn has-alert"><Icon name="bell"/><i/></button><button className="icon-btn hide-tablet"><Icon name="help"/></button><button className="profile-button" onClick={()=>setRoleMenu(!roleMenu)}><Avatar initials={profile.initials} tone={2}/><span><strong>{profile.name}</strong><small>{role}</small></span><Icon name="chevron" size={14}/></button></div>{roleMenu&&<div className="role-menu"><span className="eyebrow">SWITCH EXPERIENCE</span>{(Object.keys(roleProfiles) as Role[]).map((r,i)=><button className={r===role?"active":""} key={r} onClick={()=>{setRole(r);setRoleMenu(false);navigate("Dashboard")}}><Avatar initials={roleProfiles[r].initials} tone={i}/><span><strong>{r}</strong><small>{r===role?"Current role":"Switch dashboard & access"}</small></span>{r===role&&<Icon name="check"/>}</button>)}<div className="role-menu-divider"/><button onClick={()=>{clearToken();setLiveSession(null);setRoleMenu(false);setAuthenticated(false)}}><span className="list-icon tone-amber"><Icon name="arrow"/></span><span><strong>Sign out</strong><small>Return to secure access gateway</small></span></button></div>}</header>
      <div className="crumbbar"><div><button onClick={()=>navigate(module)}>{module}</button><Icon name="chevron" size={13}/><button onClick={()=>navigate(module,sub)}>{sub}</button>{detail&&<><Icon name="chevron" size={13}/><strong>{(()=>{const raw=detail.startsWith("cid:")?"Course":detail.includes(":")?(detail.split(":").at(-1)||detail):detail;try{return decodeURIComponent(raw)}catch{return raw}})()}</strong></>}</div><span className="demo-label">{liveSession?`LIVE API · ${liveSession.auth_mode.toUpperCase()}`:"DEMO ENVIRONMENT · SAMPLE DATA"}</span></div>
      <main className="main-content">{["Learning Intelligence","Learning Paths","AI Study Buddy","Adaptive Learning","Student Success","Assignments","Assessments","Gamification","Data Security & Privacy"].includes(module)?<div className="li-shell"><nav className={`li-subnav ${module!=="Learning Intelligence"?"deep-module-nav":""}`} aria-label={`${module} sections`}>{submodules[module].filter(item=>!(role==="Student"&&((module==="Assignments"&&item!=="Assignments")||(module==="Assessments"&&item!=="Assessments")))&&!(module==="Gamification"&&item==="Game Configuration"&&!["Teacher / Faculty","Administrator"].includes(role))&&!(role==="Training Coordinator"&&module==="Assessments"&&!(["Results","Proctoring"].includes(item)))).map((item,i)=><button className={sub===item?"active":""} key={item} onClick={()=>navigate(module,item)}><Icon name={(module==="Learning Paths"?["path","brain","warning","spark","assessment","trophy"]:module==="Gamification"?["library","trophy","assessment","file","chart","credential","ops"]:module==="Data Security & Privacy"?["shield","data","library","assessment","people","report"]:module==="Assessments"?["assessment","file","wand","calendar","file","grade","assessment","chart","shield"]:module==="Assignments"?["assignment","file","grade","assessment","shield","chat"]:module==="Student Success"?["home","student","warning","people","brain","success","shield","trend","check","chart","path"]:module==="Adaptive Learning"?["home","path","brain","data","chart","assessment","spark","credential","trophy","govern"]:module==="AI Study Buddy"?["chat","path","assessment","spark","calendar","clock","file","file","assessment","chart","spark","chat"]:["home","brain","wand","spark","path","chart"])[i] as IconName}/><span>{item}</span></button>)}</nav>{content}</div>:content}</main>
    </div>
    {copilot&&<aside className="copilot-drawer"><div className="copilot-head"><div className="ai-avatar"><Icon name="spark"/></div><div><h2>IntelUniVen AI Copilot</h2><span><i/> Aware of {module}</span></div><button onClick={()=>setCopilot(false)}><Icon name="close"/></button></div><div className="copilot-context"><span className="eyebrow">CURRENT CONTEXT</span><strong>{module} / {sub}</strong><small>Responses respect your {role.toLowerCase()} permissions.</small></div><div className="copilot-chat"><div className="copilot-welcome"><div className="ai-orb"><Icon name="spark"/></div><h3>How can I help?</h3><p>I can analyze this page and help you take the next step.</p></div><button className="prompt-card">{contextPrompt}<Icon name="chevron"/></button>{["Summarize what needs attention","Explain the key trends","Recommend next actions"].map(x=><button className="prompt-card" key={x}>{x}<Icon name="chevron"/></button>)}</div><div className="copilot-input"><input placeholder={`Ask about ${module.toLowerCase()}...`}/><button><Icon name="send"/></button></div><small className="permission-note"><Icon name="shield" size={13}/> Role permissions and data privacy enforced</small></aside>}
    {search&&<div className="modal-backdrop" onClick={()=>setSearch(false)}><section className="search-modal" onClick={e=>e.stopPropagation()}><div className="search-modal-input"><Icon name="search"/><input autoFocus placeholder={role==="Student"?'Try "Continue my Oracle SQL training"':'Search within your authorized scope'}/><kbd>ESC</kbd></div><div className="search-content"><span className="eyebrow">SUGGESTED SEARCHES</span>{searchSuggestions.map(([x,target,icon],i)=><button key={x} onClick={()=>{setSearch(false);navigate(target)}}><span className={`list-icon tone-${i===1?"violet":"blue"}`}><Icon name={icon as IconName}/></span><span><strong>{x}</strong><small>{role==="Student"?"My authorized learning content":`${role} scope · Permission-aware`}</small></span><Icon name="chevron"/></button>)}</div><div className="search-footer"><span><kbd>↑</kbd><kbd>↓</kbd> Navigate</span><span><kbd>↵</kbd> Open</span><span><Icon name="shield" size={13}/> Results respect role permissions</span></div></section></div>}
  </div>;
}
